    --line: #e5e7eb;
    --bg: #ffffff;
    --bg-soft: #fafafa;
    --maxw: 900px;
  }
  * { box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: var(--ink); background: var(--bg);
    line-height: 1.65; font-size: 17px; -webkit-font-smoothing: antialiased;
  }
  a { color: var(--blue); text-decoration: none; }
  a:hover { text-decoration: underline; }

  /* Nav */
  nav {
    position: sticky; top: 0; z-index: 10;
    background: rgba(255,255,255,0.85);
    backdrop-filter: saturate(180%) blur(10px);
    border-bottom: 1px solid var(--line);
  }
  .nav-inner {
    max-width: var(--maxw); margin: 0 auto; padding: 14px 24px;
    display: flex; align-items: center; justify-content: space-between;
    flex-wrap: wrap; gap: 8px;
  }
  .brand { font-weight: 700; letter-spacing: -0.01em; font-size: 15px; }
  .brand .code { color: var(--red); }
  .nav-links { display: flex; gap: 22px; font-size: 14px; }
  .nav-links a { color: var(--muted); }
  .nav-links a:hover { color: var(--ink); text-decoration: none; }

  /* Layout */
  section { max-width: var(--maxw); margin: 0 auto; padding: 72px 24px; }
  section + section { border-top: 1px solid var(--line); }

  /* Section headers */
  .head { display: flex; align-items: center; gap: 14px; margin: 0 0 32px; }
  .head .ico {
    flex: none; width: 40px; height: 40px; border-radius: 10px;
    display: grid; place-items: center;
    background: linear-gradient(135deg, #eff6ff, #fef2f2); color: var(--blue);
  }
  .head .ico svg { width: 22px; height: 22px; }
  .kicker {
    display: block; font-size: 12px; font-weight: 700; letter-spacing: 0.09em;
    text-transform: uppercase; color: var(--red); margin-bottom: 2px;
  }
  .head h2 { font-size: 32px; margin: 0; font-weight: 800; letter-spacing: -0.02em; line-height: 1.15; }

  /* Hero */
  .hero-wrap { border-bottom: 1px solid var(--line); overflow: hidden; position: relative; }
  .hero { max-width: var(--maxw); margin: 0 auto; padding: 96px 24px 84px; position: relative; z-index: 1; }
  .hero-art {
    position: absolute; top: 0; right: 0; height: 100%; width: 46%;
    opacity: 0.9; pointer-events: none; z-index: 0;
    -webkit-mask-image: linear-gradient(90deg, transparent, #000 40%);
            mask-image: linear-gradient(90deg, transparent, #000 40%);
  }
  .hero-art svg { height: 100%; width: 100%; }
  .eyebrow {
    display: inline-block; font-size: 13px; font-weight: 600; color: var(--red);
    letter-spacing: 0.06em; text-transform: uppercase; margin-bottom: 18px;
  }
  .hero h1 { font-size: 56px; margin: 0 0 22px; font-weight: 800; letter-spacing: -0.03em; line-height: 1.05; max-width: 620px; }
  .hero p.lede { font-size: 21px; color: var(--muted); max-width: 560px; margin: 0; }
  .accent-bar { width: 72px; height: 5px; margin-top: 30px; background: linear-gradient(90deg, var(--blue), var(--red)); border-radius: 3px; }

  /* Prose + goals */
  .prose { max-width: 680px; }
  .prose p { margin: 0 0 18px; }
  .prose p:last-child { margin-bottom: 0; }
  .goals { list-style: none; padding: 0; margin: 0; display: grid; gap: 4px; }
  .goals li { padding: 18px 0; border-bottom: 1px solid var(--line); display: flex; gap: 18px; align-items: baseline; }
  .goals li:last-child { border-bottom: none; }
  .goals .num { color: var(--blue); font-weight: 800; font-size: 20px; font-variant-numeric: tabular-nums; min-width: 30px; }

  /* ===== JOURNEY / TIMELINE ===== */
  .journey { position: relative; margin-top: 8px; }
  .journey::before {
    content: ""; position: absolute; left: 19px; top: 14px; bottom: 18px;
    width: 2px; background: var(--line);
  }

  /* Chapter dividers */
  .chapter { position: relative; padding-left: 56px; margin: 40px 0 22px; }
  .chapter:first-child { margin-top: 0; }
  .chap-node {
    position: absolute; left: 9px; top: 4px; width: 22px; height: 22px; border-radius: 50%;
    background: linear-gradient(135deg, var(--blue), var(--red)); box-shadow: 0 0 0 4px var(--bg);
  }
  .chap-kicker { display: block; font-size: 12px; font-weight: 700; letter-spacing: 0.09em; text-transform: uppercase; color: var(--red); }
  .chap-title { font-size: 22px; font-weight: 800; letter-spacing: -0.02em; line-height: 1.2; }

  /* Stations */
  .station { position: relative; padding: 0 0 30px 56px; }
  .station:last-child { padding-bottom: 0; }
  .node {
    position: absolute; left: 12px; top: 5px; width: 16px; height: 16px; border-radius: 50%;
    background: var(--bg); border: 2px solid var(--blue); box-shadow: 0 0 0 4px var(--bg); box-sizing: border-box;
  }
  .st-date { font-size: 13px; font-weight: 600; color: var(--muted); font-variant-numeric: tabular-nums; }
  .st-title { font-size: 19px; font-weight: 700; margin: 2px 0 8px; letter-spacing: -0.01em; }
  .st-tags { display: flex; flex-wrap: wrap; gap: 4px; }
  .star { color: var(--red); font-weight: 700; }

  .tag { display: inline-block; font-size: 12px; font-weight: 600; padding: 2px 9px; border-radius: 999px; white-space: nowrap; }
  .tag.disc { background: #eff6ff; color: var(--blue-dark); }
  .tag.assign { background: #fef2f2; color: var(--red); }
  .tag.extra { background: #f4f4f5; color: var(--muted); }

  /* Date-aware states */
  .station.past { opacity: 0.5; }
  .station.past .node { background: var(--line); border-color: var(--line); }
  .station.future .node { background: var(--bg); border-color: var(--blue); }
  .station.current .node {
    background: var(--red); border-color: var(--red);
    box-shadow: 0 0 0 4px var(--bg), 0 0 0 7px rgba(220,38,38,0.25);
  }
  .here-badge {
    display: inline-block; vertical-align: middle; margin-left: 10px;
    font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase;
    color: #fff; background: var(--red); padding: 3px 9px; border-radius: 999px;
  }
  @media (prefers-reduced-motion: no-preference) {
    .station.current .node { animation: pulse 2.2s ease-in-out infinite; }
    @keyframes pulse {
      0%, 100% { box-shadow: 0 0 0 4px var(--bg), 0 0 0 7px rgba(220,38,38,0.28); }
      50%      { box-shadow: 0 0 0 4px var(--bg), 0 0 0 10px rgba(220,38,38,0.10); }
    }
  }

  /* Break marker */
  .brk { position: relative; padding-left: 56px; margin: 6px 0 24px; }
  .brk .node { background: var(--bg-soft); border: 2px dashed var(--muted); }
  .brk span { font-size: 14px; font-style: italic; color: var(--muted); }

  /* Assignments */
  .cards { display: grid; gap: 16px; grid-template-columns: repeat(3, 1fr); }
  .card { border: 1px solid var(--line); border-radius: 12px; padding: 22px; border-top: 3px solid var(--red); }
  .card h3 { margin: 0 0 6px; font-size: 18px; }
  .card .due { font-size: 13px; color: var(--muted); font-weight: 600; }
  .card p { margin: 10px 0 0; font-size: 14px; color: var(--muted); }

  /* Info */
  .info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; }
  .info-grid dt { font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); }
  .info-grid dd { margin: 4px 0 20px; }

  footer { max-width: var(--maxw); margin: 0 auto; padding: 40px 24px 64px; border-top: 1px solid var(--line); color: var(--muted); font-size: 14px; }

  @media (max-width: 720px) {
    .hero h1 { font-size: 40px; }
    .hero p.lede { font-size: 18px; }
    .hero-art { display: none; }
    .head h2 { font-size: 26px; }
