<script>
  // Date-aware "You are here" — runs in the student's browser, so it always reflects today.
  (function () {
    var today = new Date(); today.setHours(0, 0, 0, 0);
    var stations = document.querySelectorAll('.station');
    var currentSet = false;
    stations.forEach(function (st) {
      var due = new Date(st.getAttribute('data-date') + 'T00:00:00');
      if (due < today) {
        st.classList.add('past');
      } else if (!currentSet) {
        st.classList.add('current');
        currentSet = true;
        var badge = document.createElement('span');
        badge.className = 'here-badge';
        badge.textContent = 'You are here';
        st.querySelector('.st-title').appendChild(badge);
      } else {
        st.classList.add('future');
      }
    });
  })();
</script>

