    --ink: #18181b;
    --muted: #6b7280;
    --line: #e5e7eb;
    --bg: #ffffff;
    --bg-soft: #fafafa;
    --maxw: 900px;
    --mono:
      ui-monospace, SFMono-Regular, Menlo,
      Consolas, "Liberation Mono", monospace;
  }

  * {
    box-sizing: border-box;
  }

  html {
    scroll-behavior: smooth;
  }

  body {
    margin: 0;
    font-family:
      -apple-system, BlinkMacSystemFont, "Segoe UI",
      Roboto, Helvetica, Arial, sans-serif;
    color: var(--ink);
    background: var(--bg);
    line-height: 1.65;
    font-size: 17px;
    -webkit-font-smoothing: antialiased;
  }

  a {
    color: var(--blue);
    text-decoration: none;
  }
  a:hover {
    text-decoration: underline;
  }

  /* Nav */
  nav {
    position: sticky;
    top: 0;
    z-index: 10;
    background: rgba(255, 255, 255, 0.85);
    backdrop-filter: saturate(180%) blur(10px);
    border-bottom: 1px solid var(--line);
  }
  .nav-inner {
    max-width: var(--maxw);
    margin: 0 auto;
    padding: 14px 24px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 8px;
  }
  .brand {
    font-weight: 700;
    letter-spacing: -0.01em;
    font-size: 15px;
  }
  .brand .code {
    font-family: var(--mono);
    color: var(--red);
  }
  .nav-links {
    display: flex;
    gap: 20px;
    font-size: 14px;
  }
  .nav-links a {
    color: var(--muted);
  }
  .nav-links a:hover {
    color: var(--ink);
    text-decoration: none;
  }

  /* Layout */
  section {
    max-width: var(--maxw);
    margin: 0 auto;
    padding: 72px 24px;
  }
  section + section {
    border-top: 1px solid var(--line);
  }

  /* Section headers */
  .head {
    display: flex;
    align-items: center;
    gap: 14px;
    margin: 0 0 32px;
  }
  .head .ico {
    flex: none;
    width: 42px;
    height: 42px;
    border-radius: 8px;
    display: grid;
    place-items: center;
    background: linear-gradient(135deg, #eff6ff, #fef2f2);
  }
  .head .ico svg {
    width: 22px;
    height: 22px;
  }
  .kicker {
    display: block;
    font-family: var(--mono);
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--red);
    margin-bottom: 3px;
  }
  .head h2 {
    font-size: 32px;
    margin: 0;
    font-weight: 800;
    letter-spacing: -0.02em;
    line-height: 1.15;
  }

  /* Hero */
  .hero-wrap {
    border-bottom: 1px solid var(--line);
    overflow: hidden;
    position: relative;
  }
  .hero {
    max-width: var(--maxw);
    margin: 0 auto;
    padding: 96px 24px 84px;
    position: relative;
    z-index: 1;
  }
  .hero-art {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: 46%;
    opacity: 0.9;
    pointer-events: none;
    z-index: 0;
    -webkit-mask-image:
      linear-gradient(90deg, transparent, #000 40%);
    mask-image:
      linear-gradient(90deg, transparent, #000 40%);
  }
  .hero-art svg {
    height: 100%;
    width: 100%;
  }
  .eyebrow {
    display: inline-block;
    font-family: var(--mono);
    font-size: 13px;
    font-weight: 600;
