    letter-spacing: -0.03em;
    line-height: 1.05;
    max-width: 620px;
  }
  .hero p.lede {
    font-size: 21px;
    color: var(--muted);
    max-width: 560px;
    margin: 0;
  }
  .accent-bar {
    width: 72px;
    height: 5px;
    margin-top: 30px;
    background: linear-gradient(90deg, var(--blue), var(--red));
    border-radius: 2px;
  }

  /* Prose + goals */
  .prose {
    max-width: 680px;
  }
  .prose p {
    margin: 0 0 18px;
  }
  .prose p:last-child {
    margin-bottom: 0;
  }
  .goals {
    list-style: none;
    padding: 0;
    margin: 0;
    display: grid;
    gap: 4px;
  }
  .goals li {
    padding: 18px 0;
    border-bottom: 1px solid var(--line);
    display: flex;
    gap: 18px;
    align-items: baseline;
  }
  .goals li:last-child {
    border-bottom: none;
  }
  .goals .num {
    font-family: var(--mono);
