    font-weight: 700;
    font-size: 18px;
    min-width: 34px;
  }

  /* ===== JOURNEY / TIMELINE ===== */
  .journey {
    position: relative;
    padding: 24px 0;
    margin-top: 8px;
  }
  .journey::before {
    content: "";
    position: absolute;
    left: 19px;
    top: 16px;
