    position: absolute;
    left: 14px;
    width: 12px;
    height: 12px;
    border-radius: 2px;
    z-index: 1;
  }
  .rail-cap.start {
    top: 6px;
    background: var(--bg);
    border: 2px solid var(--blue);
  }
  .rail-cap.end {
    bottom: 6px;
    background: linear-gradient(135deg, var(--blue), var(--red));
  }

  /* Chapter dividers with pixel emblems */
  .chapter {
    position: relative;
    padding-left: 56px;
    margin: 40px 0 22px;
    min-height: 30px;
  }
  .chapter:first-child {
    margin-top: 0;
  }
  .emblem {
    position: absolute;
    left: 6px;
    top: -2px;
    width: 28px;
    height: 28px;
    background: var(--bg);
    display: grid;
