    z-index: 1;
  }
  .emblem svg {
    width: 22px;
    height: 22px;
  }
  .chap-kicker {
    display: block;
    font-family: var(--mono);
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.06em;
