    color: var(--red);
  }
  .chap-title {
    font-size: 22px;
    font-weight: 800;
    letter-spacing: -0.02em;
    line-height: 1.2;
  }

  /* Stations */
  .station {
    position: relative;
    padding: 0 0 30px 56px;
  }
  .station:last-child {
    padding-bottom: 0;
  }
  .node {
    position: absolute;
    left: 12px;
    top: 5px;
    width: 16px;
    height: 16px;
    border-radius: 2px;
    background: var(--bg);
    border: 2px solid var(--blue);
    box-shadow: 0 0 0 4px var(--bg);
    box-sizing: border-box;
    z-index: 1;
  }
  .st-date {
    font-family: var(--mono);
    font-size: 12px;
    font-weight: 600;
    color: var(--muted);
    letter-spacing: 0.02em;
  }
  .st-title {
    font-size: 19px;
    font-weight: 700;
    margin: 2px 0 8px;
    letter-spacing: -0.01em;
  }
  .st-link {
    color: inherit;
    text-decoration: none;
  }
  .st-link:hover {
    color: var(--blue);
  }
  .st-tags {
    display: flex;
    flex-wrap: wrap;
