  .tag.assign {
    background: #fef2f2;
    color: var(--red);
  }
  .tag.extra {
    background: #f4f4f5;
    color: var(--muted);
  }

  /* Date-aware states */
  .station.past {
    opacity: 0.5;
  }
  .station.past .node {
    background: var(--line);
    border-color: var(--line);
  }
  .station.future .node {
    background: var(--bg);
    border-color: var(--blue);
  }
  .station.current .node {
    background: var(--red);
    border-color: var(--red);
