  @media (prefers-reduced-motion: no-preference) {
    .station.current .node {
      animation: pulse 2.2s ease-in-out infinite;
    }
    @keyframes pulse {
      0%, 100% {
        box-shadow:
          0 0 0 4px var(--bg),
          0 0 0 7px rgba(220, 38, 38, 0.28);
      }
      50% {
