  /* Assignments (record cards) */
  .cards {
    display: grid;
    gap: 16px;
    grid-template-columns: repeat(3, 1fr);
  }
  .card {
    position: relative;
    display: block;
    border: 1px solid var(--line);
    border-radius: 10px;
    padding: 24px 22px 22px;
    overflow: hidden;
    color: inherit;
    text-decoration: none;
    transition: border-color 0.15s ease, transform 0.15s ease;
  }
  .card::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, var(--blue), var(--red));
  }
  .card:hover {
    border-color: var(--blue);
    transform: translateY(-2px);
    text-decoration: none;
  }
  .reg {
    position: absolute;
    width: 5px;
    height: 5px;
    border-radius: 1px;
    background: var(--line);
  }
  .reg.tr {
    top: 12px;
    right: 12px;
  }
  .reg.bl {
    bottom: 12px;
    left: 12px;
  }
  .card:hover .reg {
    background: var(--blue);
  }
  .card-tag {
    font-family: var(--mono);
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.05em;
    color: var(--blue);
