  .grade-track {
    height: 8px;
    background: var(--bg-soft);
    border: 1px solid var(--line);
    border-radius: 2px;
    overflow: hidden;
  }
  .grade-fill {
    display: block;
    height: 100%;
    background: linear-gradient(90deg, var(--blue), var(--red));
  }
  .grade-pct {
    font-family: var(--mono);
    font-size: 14px;
    color: var(--muted);
    text-align: right;
  }

  /* Info */
  .info-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 32px;
  }
  .info-grid dt {
    font-family: var(--mono);
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--muted);
  }
  .info-grid dd {
    margin: 4px 0 20px;
  }

  footer {
